<script setup>
import{ref,reactive,onMounted}from'vue'
import{getRequests,createQuote,getOrders,updateProgress,shipOrder,advanceLogistics,getLogistics,getCreatorWorks,createCreatorWork,updateCreatorWork,deleteCreatorWork,uploadCreatorWork}from'../api'
import{ElMessage,ElMessageBox}from'element-plus'
const active=ref('works'),requests=ref([]),orders=ref([]),works=ref([]),dialogs=ref({}),logistics=ref({}),workDialog=ref(false),editingId=ref(null),uploading=ref(false)
const quoteForm=reactive({price:0,leadDays:10,note:''}),workForm=reactive({title:'',category:'木作',price:199,leadDays:10,summary:'',image:''})
const categories=['陶艺','木作','编织','织染','刺绣','皮艺','银饰']
const statusText=s=>({APPROVED:'已上架',PENDING:'待审核',REJECTED:'审核驳回'}[s]||s),statusType=s=>({APPROVED:'success',PENDING:'warning',REJECTED:'danger'}[s]||'info')
async function load(){requests.value=(await getRequests()).data;orders.value=(await getOrders()).data;works.value=(await getCreatorWorks()).data;for(const o of orders.value){try{logistics.value[o.id]=(await getLogistics(o.id)).data}catch{}}}
async function quote(r){await createQuote({requestId:r.id,price:quoteForm.price,leadDays:quoteForm.leadDays,note:quoteForm.note});ElMessage.success('报价已提交');dialogs.value[r.id]=false;load()}
async function step(o,p,t){await updateProgress(o.id,{progress:p,text:t});ElMessage.success('制作进度已更新');load()}
async function ship(o){await shipOrder(o.id,{carrier:'顺丰速运（模拟）',trackingNo:''});ElMessage.success('模拟发货成功');load()}
async function advance(o){await advanceLogistics(o.id);ElMessage.success('模拟物流轨迹已更新');load()}
function openCreate(){editingId.value=null;Object.assign(workForm,{title:'',category:'木作',price:199,leadDays:10,summary:'',image:''});workDialog.value=true}
function openEdit(w){editingId.value=w.id;Object.assign(workForm,{title:w.title,category:w.category,price:w.price,leadDays:w.leadDays,summary:w.summary,image:w.image});workDialog.value=true}
async function saveWork(){try{if(editingId.value)await updateCreatorWork(editingId.value,workForm);else await createCreatorWork(workForm);ElMessage.success(editingId.value?'作品已更新并重新提交审核':'作品已创建并提交审核');workDialog.value=false;await load()}catch(e){ElMessage.error(e.response?.data?.message||'保存失败')}}
async function removeWork(w){try{await ElMessageBox.confirm('删除后无法恢复，确认删除“'+w.title+'”？','删除作品',{type:'warning'});await deleteCreatorWork(w.id);ElMessage.success('作品已删除');load()}catch(e){}}
async function upload(e){const file=e.target.files?.[0];if(!file)return;try{uploading.value=true;workForm.image=(await uploadCreatorWork(file)).data.url;ElMessage.success('图片上传成功')}catch(err){ElMessage.error(err.response?.data?.message||'上传失败')}finally{uploading.value=false;e.target.value=''}}
onMounted(load)
</script>
<template><section class="page-hero"><div class="container"><h1>商户创作工作台</h1><p>管理作品、参与定制报价、跟踪制作进度和物流交付。</p></div></section>
<section class="section"><div class="container"><div class="creator-summary"><div class="metric"><small>我的作品</small><b>{{works.length}}</b></div><div class="metric"><small>待审核</small><b>{{works.filter(w=>w.status==='PENDING').length}}</b></div><div class="metric"><small>开放需求</small><b>{{requests.filter(r=>r.status==='待报价').length}}</b></div><div class="metric"><small>进行中订单</small><b>{{orders.filter(o=>!['已完成','已取消'].includes(o.status)).length}}</b></div></div>
<el-tabs v-model="active" class="workspace-tabs">
<el-tab-pane label="作品管理" name="works"><div class="section-head"><div><h2 style="font-size:24px">作品管理</h2><p>新增或修改作品后进入管理员审核，通过后才会展示给客户。</p></div><button class="primary-btn" @click="openCreate">+ 发布新作品</button></div>
<div class="panel"><el-table :data="works"><el-table-column label="作品" min-width="250"><template #default="{row}"><div class="table-work"><img :src="row.image"/><div><b>{{row.title}}</b><small>{{row.category}} · ¥{{row.price}} · {{row.leadDays}}天</small></div></div></template></el-table-column><el-table-column label="审核状态" width="120"><template #default="{row}"><el-tag :type="statusType(row.status)">{{statusText(row.status)}}</el-tag></template></el-table-column><el-table-column prop="likes" label="喜欢" width="80"/><el-table-column label="首页精选" width="90"><template #default="{row}">{{row.featured?'是':'否'}}</template></el-table-column><el-table-column label="操作" width="160"><template #default="{row}"><el-button size="small" @click="openEdit(row)">编辑</el-button><el-button size="small" type="danger" text @click="removeWork(row)">删除</el-button></template></el-table-column></el-table></div></el-tab-pane>
<el-tab-pane label="需求报价" name="demands"><div class="section-head"><div><h2 style="font-size:24px">定制需求大厅</h2><p>查看客户预算、材质和时间要求后提交制作方案。</p></div></div><div class="request-grid"><div class="panel" v-for="r in requests" :key="r.id"><div class="order-title-row"><b>{{r.title}}</b><span class="status">{{r.status}}</span></div><p class="body-copy">{{r.description}}</p><div class="request-meta"><span>{{r.category}} · ¥{{r.budgetMin}}-{{r.budgetMax}} · {{r.preferredMaterial}}</span><el-button size="small" :disabled="r.status!=='待报价'" @click="dialogs[r.id]=true">给出报价</el-button></div><el-dialog v-model="dialogs[r.id]" title="提交制作方案" width="430px"><el-form label-position="top"><el-form-item label="报价"><el-input-number v-model="quoteForm.price" :min="1" style="width:100%"/></el-form-item><el-form-item label="预计工期（天）"><el-input-number v-model="quoteForm.leadDays" :min="1" style="width:100%"/></el-form-item><el-form-item label="方案说明"><el-input v-model="quoteForm.note" type="textarea" :rows="4"/></el-form-item></el-form><template #footer><el-button @click="dialogs[r.id]=false">取消</el-button><el-button type="primary" @click="quote(r)">提交报价</el-button></template></el-dialog></div></div></el-tab-pane>
<el-tab-pane label="制作与物流" name="orders"><div class="section-head"><div><h2 style="font-size:24px">定制订单</h2><p>按状态更新制作进度，完成后进入发货与物流流程。</p></div></div><div class="order-work-grid"><div class="panel creator-order" v-for="o in orders" :key="o.id"><div class="order-title-row"><b>{{o.workTitle}}</b><span class="status">{{o.status}}</span></div><div class="subtle">客户：{{o.customerName}} · 订单金额 ¥{{o.amount}}</div><el-progress :percentage="o.progress" color="#a65f3f" style="margin:12px 0"/><p class="subtle">{{o.progressText}}</p><div class="creator-actions"><el-button v-if="o.status==='待制作'" size="small" @click="step(o,20,'已确认订单，开始准备材料')">开始制作</el-button><template v-if="o.status==='制作中'"><el-button size="small" @click="step(o,60,'主体制作完成，进入细节处理')">主体完成</el-button><el-button size="small" type="primary" @click="step(o,100,'作品制作完成并完成质检，等待发货')">制作完成</el-button></template><el-button v-if="o.status==='待发货'" size="small" type="primary" @click="ship(o)">模拟发货</el-button><el-button v-if="['已发货','运输中'].includes(o.status)" size="small" @click="advance(o)">模拟物流更新</el-button></div><div v-if="logistics[o.id]?.shipment" class="shipping-card"><b>{{logistics[o.id].shipment.carrier}}</b><span>{{logistics[o.id].shipment.trackingNo}}</span><small>{{logistics[o.id].shipment.status}}</small></div></div></div></el-tab-pane>
</el-tabs></div></section>
<el-dialog v-model="workDialog" :title="editingId?'编辑作品':'发布新作品'" width="620px"><el-form label-position="top"><div class="form-grid"><el-form-item label="作品名称"><el-input v-model="workForm.title"/></el-form-item><el-form-item label="品类"><el-select v-model="workForm.category" style="width:100%"><el-option v-for="c in categories" :key="c" :label="c" :value="c"/></el-select></el-form-item><el-form-item label="参考价格"><el-input-number v-model="workForm.price" :min="1" style="width:100%"/></el-form-item><el-form-item label="制作周期（天）"><el-input-number v-model="workForm.leadDays" :min="1" style="width:100%"/></el-form-item><el-form-item label="作品说明" class="form-full"><el-input v-model="workForm.summary" type="textarea" :rows="4" maxlength="800" show-word-limit/></el-form-item><el-form-item label="作品主图" class="form-full"><div class="upload-row"><img v-if="workForm.image" :src="workForm.image" class="upload-preview"/><label class="upload-button"><input type="file" accept="image/*" @change="upload" hidden/><span>{{uploading?'上传中…':'选择并上传图片'}}</span></label><el-input v-model="workForm.image" placeholder="也可以直接填写图片地址"/></div></el-form-item></div></el-form><template #footer><el-button @click="workDialog=false">取消</el-button><el-button type="primary" @click="saveWork">提交审核</el-button></template></el-dialog>
</template>